DROP TABLE IF EXISTS `article_evaluations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `article_evaluations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `article_id` int DEFAULT NULL,
  `llm_label` varchar(50) DEFAULT NULL,
  `human_label` varchar(50) DEFAULT NULL,
  `is_verified` tinyint(1) DEFAULT NULL,
  `verified_at` datetime DEFAULT NULL,
  `verified_by` int DEFAULT NULL,
  `keyword_is_correct` tinyint(1) DEFAULT NULL,
  `corrected_keyword` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_article_evaluations_article_id` (`article_id`),
  KEY `verified_by` (`verified_by`),
  KEY `ix_article_evaluations_id` (`id`),
  CONSTRAINT `article_evaluations_ibfk_1` FOREIGN KEY (`article_id`) REFERENCES `article_identity` (`id`),
  CONSTRAINT `article_evaluations_ibfk_2` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=747 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
