DROP TABLE IF EXISTS `context_signal_reviews`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `context_signal_reviews` (
  `id` int NOT NULL AUTO_INCREMENT,
  `article_id` int NOT NULL,
  `reviewer_id` int NOT NULL,
  `reviewed_at` datetime NOT NULL,
  `version` int NOT NULL DEFAULT '1',
  `request_id` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `decision` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_superseded` tinyint(1) NOT NULL DEFAULT '0',
  `signal_evidence` text COLLATE utf8mb4_unicode_ci,
  `reason` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `disease_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `disease_source` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `location` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `event_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_csr_request` (`request_id`),
  KEY `reviewer_id` (`reviewer_id`),
  KEY `event_id` (`event_id`),
  KEY `ix_context_signal_reviews_article_current` (`article_id`,`is_superseded`),
  CONSTRAINT `context_signal_reviews_ibfk_1` FOREIGN KEY (`article_id`) REFERENCES `article_identity` (`id`) ON DELETE CASCADE,
  CONSTRAINT `context_signal_reviews_ibfk_2` FOREIGN KEY (`reviewer_id`) REFERENCES `users` (`id`),
  CONSTRAINT `context_signal_reviews_ibfk_3` FOREIGN KEY (`event_id`) REFERENCES `news_events` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
