INSERT INTO `llm_evaluation_items` VALUES (1307,'3290d35c4f7bcb0b4ed03a2833c08335b398c47ae974bfa17347fbaf6500cbbb','canonical_url','bf13fb97c282c19c2bc752b7ef68be1c5415eace27c25a1f6f54a4b63d23967a','https://tuoitre.vn/mot-benh-nhi-o-thanh-hoa-chet-do-viem-nao-nhat-ban-20260507173729192.htm',834,'tuoitre.vn','2026-05-08 08:22:28','Một bệnh nhi ở Thanh Hóa chết do viêm não Nhật Bản','Ngày 7-5, nguồn tin từ Trung tâm Kiểm soát bệnh tật tỉnh Thanh Hóa cho biết vừa ghi nhận một bệnh nhi chết do viêm não Nhật Bản. Bệnh nhi 14 tuổi, trú tại phường Đông Sơn.','relevant',NULL,NULL,NULL,NULL,NULL,'reviewed',1,3,'2026-05-09 17:34:57',0,1327,1327,'2026-09-21 14:43:15','2026-09-21 14:43:15'),(1308,'c63362c50fcd63659813fc4602c3fece900c9ad15a26d51898e3f458f45682cf','canonical_url','f1c9037f171479bbedf7a4dea6ff506d5c6ab476441ed2b354add6ba15c6b9e5','https://suckhoedoisong.vn/xuat-hien-them-o-dich-sot-xuat-huyet-ha-tinh-tang-toc-phong-chong-169260509072028514.htm',846,'suckhoedoisong.vn','2026-05-09 07:45:00','Xuất hiện thêm ổ dịch sốt xuất huyết, Hà Tĩnh tăng tốc phòng chống','SKĐS - Sau khi phát hiện ổ dịch, ngành Y tế Hà Tĩnh triển khai các biện pháp phòng, chống, phun hóa chất trong bán kính 200m nhằm ngăn chặn nguy cơ bùng phát dịch trên diện rộng.','relevant',NULL,NULL,NULL,NULL,NULL,'reviewed',1,3,'2026-05-09 17:34:57',0,1328,1328,'2026-09-21 14:43:15','2026-09-21 14:43:15'),(1309,'1e03bf0539882df93bf88f9f9b3ed8bcf7f28e13083a36ea6070b8f54f6b8671','canonical_url','4287be30a386bf392382fb98eae8d515d8836d0cfa70521484e5af43ca010c29','https://vnexpress.net/be-gai-14-tuoi-tu-vong-do-viem-nao-nhat-ban-5071658.html',847,'vnexpress.net','2026-05-08 17:58:52','Bé gái 14 tuổi tử vong do viêm não Nhật Bản','Thanh Hóa Bé gái 14 tuổi sốt cao, mệt mỏi, nói ngọng, suy đa tạng vì bệnh viêm não Nhật Bản, tử vong sau 5 ngày điều trị.','relevant',NULL,NULL,NULL,NULL,NULL,'reviewed',1,3,'2026-05-09 17:34:57',0,1329,1329,'2026-09-21 14:43:15','2026-09-21 14:43:15'),(1310,'800087cdc7814e3d095362c72e41d2efa2a035145b7d4d041e6eaa2672cffe0e','canonical_url','a1ec9faba31d8d58fff28726344fd7295133fb647dd456aec8a4e3bb8e7e20ee','https://tuoitre.vn/tp-hcm-phat-hien-hon-20-000-ca-benh-lao-moi-nam-day-manh-sang-loc-qua-kham-suc-khoe-dinh-ky-20260507133456256.htm',835,'tuoitre.vn','2026-05-08 05:05:00','TP.HCM phát hiện hơn 20.000 ca bệnh lao mỗi năm, đẩy mạnh sàng lọc qua khám sức khỏe định kỳ','TP.HCM hiện là địa phương phát hiện nhiều bệnh nhân lao nhất cả nước, với 20.000 ca mỗi năm. Dự kiến trong năm 2026, TP sẽ triển khai sàng lọc bệnh lao gắn với khám sức khỏe định kỳ, các chương trình sức khỏe cộng đồng.','relevant',NULL,NULL,NULL,NULL,NULL,'reviewed',1,3,'2026-05-09 17:34:57',0,1330,1330,'2026-09-21 14:43:15','2026-09-21 14:43:15'),(1311,'1f67faeee0998e02f8ee4f9b73fb658d89b126b7c29f9f72eee7570abab637ee','canonical_url','8e144187f5afef6b6637f2029dad2c60b7ef76364ff636d1c4cae7c24e96e9d3','https://suckhoedoisong.vn/be-gai-14-tuoi-tai-thanh-hoa-tu-vong-do-viem-nao-nhat-ban-169260507175320734.htm',830,'suckhoedoisong.vn','2026-05-07 18:19:00','Bé gái 14 tuổi tại Thanh Hóa tử vong do viêm não Nhật Bản','SKĐS - Thanh Hóa ghi nhận một bé gái 14 tuổi tử vong do viêm não Nhật Bản trong tình trạng chưa tiêm vaccine và diễn tiến bệnh nhanh.','relevant',NULL,NULL,NULL,NULL,NULL,'reviewed',1,3,'2026-05-09 17:34:57',0,1331,1331,'2026-09-21 14:43:15','2026-09-21 14:43:15'),(1312,'b54c6534e233ba982f06bc35afe889bca0a89acd3cf2415787a88936aa86e9aa','canonical_url','9aaeb84d83d6e9329d0f2dc5b58021c33565b9d8ad80710a65b58a9eef660aa5','https://vnexpress.net/so-benh-nhan-lao-tang-cao-5071112.html',840,'vnexpress.net','2026-05-07 17:17:38','Số bệnh nhân lao tăng cao','Bộ Y tế ghi nhận hơn 119.000 ca bệnh lao mới trong năm 2025, tăng gần 5% so với năm trước.','relevant',NULL,NULL,NULL,NULL,NULL,'reviewed',1,3,'2026-05-09 17:34:57',0,1332,1332,'2026-09-21 14:43:15','2026-09-21 14:43:15'),(1313,'a8431a6c82352a9487bc68ae33e1cdb5174eb3a3105ebe1972e63ab3acf2d770','canonical_url','a3af4c1443b923484b2b7aa304d8c78709d7d73bbe66f3b9cef9c655deef95b6','https://thanhnien.vn/phat-hien-virus-corona-moi-o-thai-lan-co-kha-nang-lay-sang-nguoi-185260507093838036.htm',833,'thanhnien.vn','2026-05-07 11:07:00','Phát hiện virus corona mới ở Thái Lan có khả năng lây sang người','Một nhóm nhà khoa học Nhật Bản và Thái Lan thông báo một loại virus corona mới có liên quan đến loại gây ra đại dịch Covid-19 đã được phát hiện ở Thái Lan, và nó có khả năng lây nhiễm sang người.','relevant',NULL,NULL,NULL,NULL,NULL,'reviewed',1,3,'2026-05-09 17:34:57',0,1333,1333,'2026-09-21 14:43:15','2026-09-21 14:43:15'),(1314,'330cd106613ae8cf8a31390fd8665a44aae2a4420f39ab3ff84bf21f3676bcb9','canonical_url','0d49981d1f90aa5d07ca873cc586963258bbc9de710594121777cefe6b33b261','https://vov.vn/xa-hoi/phat-hien-o-dich-sot-xuat-huyet-thu-2-tai-phuong-hoanh-son-tinh-ha-tinh-post1290503.vov',851,'vov.vn','2026-05-09 23:15:42','Phát hiện ổ dịch sốt xuất huyết thứ 2 tại phường Hoành Sơn, tỉnh Hà Tĩnh','Theo thông tin từ Trung tâm Kiểm soát bệnh tật (CDC) Hà Tĩnh, \"bệnh nhân số 0\" của ổ dịch này là một bé trai sinh năm 2017. Bệnh nhi khởi phát triệu chứng từ ngày 3/5 với các dấu hiệu điển hình: sốt cao liên tục, đau đầu, đau cơ và chán ăn.','relevant',NULL,NULL,NULL,NULL,NULL,'reviewed',1,3,'2026-05-10 03:56:13',0,1334,1334,'2026-09-21 14:43:15','2026-09-21 14:43:15'),(1315,'2337770437be81a3cfb458a31f731426f99b4b4af5f3af303fb5ab78d2cd46b3','canonical_url','282a8738d8112c4c8b43baecc22d0ed93ad4aefa9e492274367eb440bf958f0f','https://thanhnien.vn/tphcm-cuu-song-be-trai-7-tuoi-mac-nao-mo-cau-185260504142622444.htm',821,'thanhnien.vn','2026-05-04 15:15:00','TP.HCM: Cứu sống bé trai 7 tuổi mắc não mô cầu','Nam bệnh nhi (7 tuổi, ở phường Long Trường, TP.HCM) sốt, lừ đừ đến ngày thứ 2 thì nổi các ban xuất huyết tập trung ở chân. Sau khi được đưa đến bệnh viện, bệnh nhi được theo dõi não mô cầu, nhiễm trùng huyết.','relevant',NULL,NULL,NULL,NULL,NULL,'reviewed',1,3,'2026-05-10 03:59:02',0,1335,1335,'2026-09-21 14:43:1