DROP TABLE IF EXISTS `llm_inference_runs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `llm_inference_runs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `evaluation_item_id` bigint NOT NULL,
  `inference_chain_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `inference_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `attempt_number` int NOT NULL,
  `run_purpose` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'production',
  `scan_run_id` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rss_sample_uuid` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_benchmark_sample` tinyint(1) NOT NULL DEFAULT '0',
  `sampling_version` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sampling_probability` float DEFAULT NULL,
  `selected_for_review_at` datetime DEFAULT NULL,
  `input_title` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `input_summary` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `input_keywords` json DEFAULT NULL,
  `input_stage1_route` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `input_signal_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `input_checksum` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `model_id` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `provider` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `prompt_version` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `prompt_template_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `few_shot_dataset_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `few_shot_dataset_version_id` bigint DEFAULT NULL,
  `schema_version` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `inference_status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `llm_label` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `llm_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `parsed_response` json DEFAULT NULL,
  `raw_response_text` text COLLATE utf8mb4_unicode_ci,
  `predicted_diseases` json DEFAULT NULL,
  `predicted_location` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `predicted_event_date` datetime DEFAULT NULL,
  `predicted_case_observations` json DEFAULT NULL,
  `requested_at` datetime NOT NULL,
  `lease_expires_at` datetime NOT NULL,
  `completed_at` datetime DEFAULT NULL,
  `latency_ms` int DEFAULT NULL,
  `error_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `error_message` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fallback_from_run_id` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_llm_inference_id` (`inference_id`),
  UNIQUE KEY `uq_llm_run_chain_attempt` (`inference_chain_id`,`attempt_number`),
  KEY `fallback_from_run_id` (`fallback_from_run_id`),
  KEY `few_shot_dataset_version_id` (`few_shot_dataset_version_id`),
  KEY `ix_llm_run_item_requested` (`evaluation_item_id`,`requested_at`),
  KEY `ix_llm_run_status_created` (`inference_status`,`created_at`),
  KEY `ix_llm_run_model_prompt` (`model_id`,`prompt_version`),
  KEY `ix_llm_run_benchmark` (`is_benchmark_sample`,`sampling_version`),
  KEY `ix_llm_run_scan` (`scan_run_id`),
  KEY `ix_llm_run_rss_sample` (`rss_sample_uuid`),
  CONSTRAINT `llm_inference_runs_ibfk_1` FOREIGN KEY (`evaluation_item_id`) REFERENCES `llm_evaluation_items` (`id`) ON DELETE CASCADE,
  CONSTRAINT `llm_inference_runs_ibfk_2` FOREIGN KEY (`fallback_from_run_id`) REFERENCES `llm_inference_runs` (`id`) ON DELETE SET NULL,
  CONSTRAINT `llm_inference_runs_ibfk_3` FOREIGN KEY (`few_shot_dataset_version_id`) REFERENCES `llm_dataset_versions` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_llm_run_success_has_label` CHECK (((`inference_status` <> _utf8mb4'success') or (`llm_label` is not null)))
) ENGINE=InnoDB AUTO_INCREMENT=2076 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
