--
-- Table structure for table `news_events`
--

DROP TABLE IF EXISTS `news_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `news_events` (
  `id` int NOT NULL AUTO_INCREMENT,
  `canonical_title` varchar(500) NOT NULL,
  `disease_name` varchar(255) NOT NULL,
  `location` varchar(255) DEFAULT NULL,
  `event_date` datetime DEFAULT NULL,
  `case_count` int DEFAULT NULL,
  `severity` varchar(50) DEFAULT NULL,
  `status` varchar(50) DEFAULT NULL,
  `fingerprint` varchar(255) NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `analyst_reviewed_at` datetime DEFAULT NULL,
  `analyst_reviewed_by` int DEFAULT NULL,
  `verified_at` datetime DEFAULT NULL,
  `verified_by` int DEFAULT NULL,
  `rejection_reason` varchar(500) DEFAULT NULL,
  `verification_notes` text,
  `verification_source` varchar(500) DEFAULT NULL,
  `verified_case_source_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_news_events_disease_name` (`disease_name`),
  KEY `ix_news_events_event_date` (`event_date`),
  KEY `ix_news_events_id` (`id`),
  KEY `ix_news_events_fingerprint` (`fingerprint`),
  KEY `fk_events_case_source` (`verified_case_source_id`),
  KEY `fk_events_reviewed_by` (`analyst_reviewed_by`),
  KEY `fk_events_verified_by` (`verified_by`),
  CONSTRAINT `fk_events_case_source` FOREIGN KEY (`verified_case_source_id`) REFERENCES `disease_cases` (`id`),
  CONSTRAINT `fk_events_reviewed_by` FOREIGN KEY (`analyst_reviewed_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_events_verified_by` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1777 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

