--
-- Table structure for table `rss_entry_samples`
--

DROP TABLE IF EXISTS `rss_entry_samples`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rss_entry_samples` (
  `id` int NOT NULL AUTO_INCREMENT,
  `source_id` int DEFAULT NULL,
  `link` varchar(767) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary` text COLLATE utf8mb4_unicode_ci,
  `published_date` datetime DEFAULT NULL,
  `sampled_at` datetime NOT NULL,
  `expires_at` datetime NOT NULL,
  `passed_stage1` tinyint(1) NOT NULL,
  `llm_label` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `predicted_disease` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `predicted_location` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `predicted_event_date` datetime DEFAULT NULL,
  `predicted_case_values` text COLLATE utf8mb4_unicode_ci,
  `article_id` int DEFAULT NULL,
  `human_relevant` tinyint(1) DEFAULT NULL,
  `labeled_by` int DEFAULT NULL,
  `labeled_at` datetime DEFAULT NULL,
  `human_disease` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `human_location` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `human_event_date` datetime DEFAULT NULL,
  `human_case_value` int DEFAULT NULL,
  `stage1_route` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gate_b_mode` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gate_b_evaluated` tinyint(1) DEFAULT NULL,
  `detector_matched` tinyint(1) DEFAULT NULL,
  `detector_version` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `context_signal_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `human_signal_label` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `llm_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `human_diseases` json DEFAULT NULL,
  `sample_uuid` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_rss_entry_sample_uuid` (`sample_uuid`),
  KEY `source_id` (`source_id`),
  KEY `article_id` (`article_id`),
  KEY `labeled_by` (`labeled_by`),
  KEY `ix_rss_samples_expires` (`expires_at`),
  CONSTRAINT `rss_entry_samples_ibfk_1` FOREIGN KEY (`source_id`) REFERENCES `rss_sources` (`id`),
  CONSTRAINT `rss_entry_samples_ibfk_2` FOREIGN KEY (`article_id`) REFERENCES `article_identity` (`id`) ON DELETE SET NULL,
  CONSTRAINT `rss_entry_samples_ibfk_3` FOREIGN KEY (`labeled_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1215 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

